import CryptoKit
import Foundation
import NetworkSpool
import Security

// MARK: - VerifyHarness — Suite 27 (continued): Krouton Server Control Channel & Client Certificate

extension KroutonTestHarness {
    /// `Vectors/krsp-control-v1.txt` is generated by the Rust server's encoder; every line must decode
    /// here and re-encode to the same JSON, so the app and the server agree on every message.
    static func verifyKroutonServerClientWire(_ h: inout KroutonTestHarness) {
        let url = Self.repositoryRoot.appendingPathComponent("Vectors/krsp-control-v1.txt")
        let lines = ((try? String(contentsOf: url, encoding: .utf8)) ?? "")
            .components(separatedBy: .newlines)
            .filter { !$0.hasPrefix("#") && $0.contains(" = ") }
        h.check(lines.count >= 21, "Control vectors must load (\(url.lastPathComponent)) and cover every message type")
        var allRoundTrip = true
        for line in lines {
            guard let range = line.range(of: " = ") else { continue }
            let name = String(line[..<range.lowerBound])
            let json = Data(line[range.upperBound...].utf8)
            guard let object = try? JSONSerialization.jsonObject(with: json) as? [String: Any],
                  let message = SpoolControl(jsonObject: object) else {
                h.check(false, "Control vector \(name) must decode")
                allRoundTrip = false
                continue
            }
            let reencoded = NSDictionary(dictionary: message.jsonObject())
            let viaFrame = SpoolControl(frame: message.frame())
            if !reencoded.isEqual(to: object) || viaFrame != message {
                h.check(false, "Control vector \(name) must re-encode to the same JSON and survive a frame round trip")
                allRoundTrip = false
            }
        }
        h.check(allRoundTrip, "Every KRSP control message decodes and re-encodes exactly as the Rust server writes it")

        let hostile = SpoolFrame(header: SpoolFrameHeader(kind: .control), payload: [UInt8](#"{"type":"auth","identityKey":"00","signature":"00"}"#.utf8))
        h.check(SpoolControl(frame: hostile) == nil, "A control message with wrong-length keys must be rejected")

        // The client certificate: built by hand (no Keychain needed here), accepted by Security,
        // and pinned by the same SHA-256-over-X9.63 rule the server applies.
        let key = P256.Signing.PrivateKey()
        let der = SpoolSelfSignedCertificate.make(publicKeyX963: key.publicKey.x963Representation, commonName: "Verify Mac",
                                                  serial: Data(repeating: 0x9C, count: 16)) { tbs in
            try? key.signature(for: tbs).derRepresentation
        }
        let certificate = der.flatMap { SecCertificateCreateWithData(nil, $0 as CFData) }
        h.check(certificate != nil, "The self-signed client certificate must parse as X.509")
        h.check(certificate.flatMap(SpoolClientIdentity.pin(of:)) == Data(SHA256.hash(data: key.publicKey.x963Representation)),
                "The certificate must carry this Mac's P-256 key, pinned as SHA-256 of its X9.63 bytes")
        h.check(SpoolSelfSignedCertificate.make(publicKeyX963: Data(repeating: 4, count: 33), commonName: "x",
                                                serial: Data([1])) { _ in Data([1]) } == nil,
                "Only uncompressed P-256 keys may be certified")
    }
}
